// Power BI study guide. Facts checked against Microsoft Learn on 2026-11-17 (see tools/config.js sources).
// Inline quiz markup is generated by quiz() so every question has the same structure as the other guides.

const esc = (t) => String(t).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const QUIZ = [
  { t: "Basics", q: "In the Power BI service, what is the current Microsoft name for what used to be called a dataset?",
    o: ["Dataflow", "Semantic model", "Workbook", "Data mart"], a: 1,
    w: "Microsoft renamed the dataset content type to semantic model in 2023. It is a rename only; nothing about how models behave changed." },
  { t: "Storage modes", q: "Which storage mode keeps a copy of the data in memory, so visuals only show new source data after a refresh?",
    o: ["Import", "DirectQuery", "Both of them equally", "Neither"], a: 0,
    w: "Import caches data in the model, which is fast and fully featured but only as fresh as the last refresh. DirectQuery sends queries to the source each time." },
  { t: "Power Query", q: "You have twelve monthly sales tables with identical columns and want a single long table. Which operation do you use?",
    o: ["Merge queries", "Append queries", "Pivot columns", "Group by"], a: 1,
    w: "Append stacks rows from tables with matching columns. Merge joins tables side by side on a key, like a SQL join." },
  { t: "Power Query", q: "You create a Reference of query A, then change a step in query A. What happens to the referenced query?",
    o: ["Nothing; it is an independent copy", "It picks up the change, because it starts from A's output", "It is deleted", "It switches to DirectQuery"], a: 1,
    w: "A referenced query starts from the output of the original, so upstream changes flow through. A Duplicate copies the steps and is independent." },
  { t: "Power Query", q: "A table has columns Jan, Feb and Mar, each holding sales. You want columns Month and Sales instead. Which transformation fits?",
    o: ["Pivot columns", "Transpose, then rename", "Unpivot columns", "Append queries"], a: 2,
    w: "Unpivot turns column headers into attribute values, giving one row per month. This long layout is what relationships, slicers and measures work best with." },
  { t: "Power Query", q: "Why do you want transformation steps to support query folding when the source is a database?",
    o: ["Folding makes columns smaller", "The work is pushed to the source as a native query, so less data is moved and processed in Power Query", "It removes the need for relationships", "It lets you skip data types"], a: 1,
    w: "When steps fold, the source does the filtering and shaping. In DirectQuery, steps that cannot fold cause errors or force you to simplify." },
  { t: "Modelling", q: "A refresh loads duplicate values into the 'one' side column of a one-to-many relationship. What happens?",
    o: ["Power BI keeps the first value", "Duplicates are merged silently", "The refresh fails", "The relationship becomes many-to-many automatically"], a: 2,
    w: "The 'one' side must contain unique values. Duplicates there make the whole refresh fail, so clean or de-duplicate the key first." },
  { t: "Modelling", q: "In a one-to-many relationship, which side is the dimension table?",
    o: ["The 'many' side", "The 'one' side", "The side with more columns", "Neither; Power BI has no table types"], a: 1,
    w: "Power BI infers table roles from relationships: the 'one' side is a dimension (filters and groups) and the 'many' side is a fact table (events to summarise)." },
  { t: "Modelling", q: "Sales has both OrderDate and ShipDate related to one Date table. How many of those relationships can be active?",
    o: ["Both", "Only one; the other must be inactive and used with USERELATIONSHIP", "None", "As many as you like if cross-filter is Both"], a: 1,
    w: "Only one active filter path can exist between two tables. For simultaneous filtering by both dates, Microsoft recommends a separate date table per role." },
  { t: "Modelling", q: "Which is a requirement for a date table used for time intelligence?",
    o: ["One row per transaction", "Unique, contiguous dates with no blanks", "Dates stored as text", "It must be the fact table"], a: 1,
    w: "A date table has one row per date, no gaps, no blanks, and unique values. Mark it as a date table for classic time intelligence." },
  { t: "DAX", q: "Which of these is calculated at query time in the current filter context and is not stored row by row in the model?",
    o: ["A calculated column", "A measure", "A calculated table", "A Power Query step"], a: 1,
    w: "Measures are evaluated when a visual needs them, in the filter context of that visual. Calculated columns are computed at refresh and stored." },
  { t: "DAX", q: "A slicer selects Color = Red. A measure is CALCULATE([Total Sales], 'Product'[Color] = \"Blue\"). What does the measure return?",
    o: ["Red sales", "Blue sales", "Zero", "Red and blue sales together"], a: 1,
    w: "A CALCULATE filter on a column overwrites any existing filter on the same column, so the slicer's Red is replaced by Blue." },
  { t: "DAX", q: "Which function do you wrap around a CALCULATE filter so that it adds to, rather than overwrites, existing filters on the same column?",
    o: ["ALL", "VALUES", "KEEPFILTERS", "USERELATIONSHIP"], a: 2,
    w: "KEEPFILTERS keeps the existing filters and intersects them with the new one." },
  { t: "DAX", q: "Why prefer DIVIDE([Profit], [Sales]) over [Profit] / [Sales]?",
    o: ["DIVIDE is always faster to type", "DIVIDE handles a zero denominator, returning BLANK or an alternate result you choose", "The / operator is not allowed in measures", "DIVIDE ignores filters"], a: 1,
    w: "DIVIDE takes an optional alternate result for division by zero and returns BLANK by default, so visuals do not show errors or infinity." },
  { t: "DAX", q: "Which function returns the same period in the previous year, for a prior-year comparison?",
    o: ["DATESYTD", "FIRSTDATE", "SAMEPERIODLASTYEAR", "EOMONTH"], a: 2,
    w: "SAMEPERIODLASTYEAR shifts the current dates back one year. DATESYTD returns the year-to-date dates of the current year." },
  { t: "DAX", q: "Revenue is Quantity times Unit Price on each row. Which measure adds this up correctly?",
    o: ["SUM(Sales[Quantity] * Sales[Price])", "SUMX(Sales, Sales[Quantity] * Sales[Price])", "SUM(Sales[Quantity]) + SUM(Sales[Price])", "COUNTROWS(Sales)"], a: 1,
    w: "SUM takes a single column. SUMX is an iterator: it evaluates the expression for every row, then adds the results." },
  { t: "Reports", q: "Which visual is the usual choice for showing a trend over time?",
    o: ["Pie chart", "Line chart", "Treemap", "Card"], a: 1,
    w: "A line chart shows change across an ordered axis such as dates. Pie charts and treemaps show part-to-whole, and a card shows one number." },
  { t: "Reports", q: "Which feature lets a user right-click a data point and jump to a detail page already filtered to that item?",
    o: ["Drillthrough", "Sync slicers", "Conditional formatting", "A theme"], a: 0,
    w: "Drillthrough passes the selected item's filter context to a target page. Sync slicers keep slicer selections consistent across pages." },
  { t: "Security", q: "A user with the Contributor role in the workspace opens a report on a semantic model that has RLS roles. What do they see?",
    o: ["Only the rows allowed by their role", "No rows at all", "All the data, because RLS does not apply to Admin, Member and Contributor", "An error"], a: 2,
    w: "RLS applies to workspace Viewers. Admin, Member and Contributor can edit the model, so they bypass row-level security." },
  { t: "Refresh", q: "A scheduled refresh fails four times in a row. What does Power BI do?",
    o: ["Retries forever", "Deactivates the refresh schedule until you fix it and turn it back on", "Deletes the semantic model", "Switches the model to DirectQuery"], a: 1,
    w: "Power BI disables the schedule after four consecutive failures (or an unrecoverable error such as expired credentials). Fix the cause, then re-enable it." },
];

// Spread the correct answer evenly over positions A-D (5 each) by rotating each question's options.
const TARGET = [2, 0, 3, 1, 2, 3, 0, 1, 3, 2, 0, 3, 1, 0, 2, 1, 3, 0, 2, 1];
function placed(it, i) {
  const shift = (TARGET[i] - it.a + 4) % 4, o = new Array(4);
  it.o.forEach((t, j) => { o[(j + shift) % 4] = t; });
  return { ...it, o, a: TARGET[i] };
}

function quiz() {
  const n = QUIZ.length;
  return QUIZ.map(placed).map((it, i) => {
    const k = i + 1;
    const opts = it.o.map((t, j) => `            <label class="opt"${j === it.a ? " data-correct" : ""}><input type="radio" name="q${k}"> ${esc(t)}</label>`).join("\n");
    return `        <div class="quiz" data-quiz>
          <div class="q-head"><span>Question ${k} of ${n}</span><span>${esc(it.t)}</span></div>
          <div class="q-body">
            <p class="q-text">${esc(it.q)}</p>
${opts}
            <button class="check-btn">Check answer</button>
          </div>
          <div class="q-explain"><b>Why:</b> ${esc(it.w)}</div>
        </div>`;
  }).join("\n");
}

const FAQ = [
  ["What is the difference between Power BI Desktop and the Power BI service?",
   "Desktop is the free Windows application where you connect to data, transform it in Power Query, build the model and design reports. The service is the online environment where you publish, share, schedule refresh, build dashboards and manage security."],
  ["Import or DirectQuery: how do you choose?",
   "Import is the default choice: fast, with the full Power Query and DAX feature set, but only as fresh as the last refresh. DirectQuery suits data that is too large to import or must always be current, but performance depends on the source, steps must fold, and queries returning more than one million rows fail unless capacity settings allow it."],
  ["What is the difference between a measure and a calculated column?",
   "A measure is evaluated at query time in the current filter context and stores only its formula. A calculated column is computed row by row at refresh and its values are stored in the model. Use measures for totals and ratios, and columns for row-level attributes you need to slice or relate on."],
  ["What does CALCULATE do?",
   "It evaluates an expression in a modified filter context. A filter argument on a column that is already filtered overwrites that filter unless you use KEEPFILTERS. With no filter arguments it performs context transition, turning row context into filter context."],
  ["Why is a star schema recommended?",
   "Each visual sends a query that filters and groups by dimension columns and summarises fact columns. Dimension tables for filtering and fact tables for summarising match that pattern, which keeps models simpler, smaller and faster than one wide table or deep snowflaked chains."],
  ["What is a role-playing dimension and how do you handle it?",
   "One dimension that filters facts in different ways, such as a date table used for order date and ship date. Only one relationship between two tables can be active. Microsoft recommends a separate table per role when you need both at once, or an inactive relationship with USERELATIONSHIP when you do not."],
  ["Why do you need a date table?",
   "Time intelligence functions such as TOTALYTD and SAMEPERIODLASTYEAR need a proper date table: unique, contiguous dates with no blanks. Create it with CALENDAR or CALENDARAUTO, or bring in an existing date dimension, and mark it as a date table."],
  ["What is the difference between merge and append in Power Query?",
   "Append stacks rows from tables that share columns. Merge joins tables side by side on key columns, with join kinds such as left outer or inner, like a SQL join."],
  ["What is the difference between Reference and Duplicate?",
   "Duplicate copies the query and its steps into an independent query. Reference creates a new query that starts from the output of the original, so changes to the original flow into it."],
  ["How does row-level security work, and who does it apply to?",
   "You define roles with DAX filter expressions in Desktop (Modeling, Manage roles), publish, then add users or groups to the roles in the service. It applies to workspace Viewers; Admin, Member and Contributor bypass it. A user in several roles gets the union of the rows. It restricts rows, not columns."],
  ["What is the difference between a report and a dashboard?",
   "A report is one or more pages of visuals built on a semantic model. A dashboard exists only in the service: a single canvas of pinned tiles, which can come from several reports and models."],
  ["A report is slow. How would you investigate?",
   "Use Performance Analyzer to find which visuals are slow and DAX query view to inspect the queries. Then remove unused rows and columns, reduce granularity where possible, move toward a star schema, and review expensive measures and relationships."],
];

const faq = () => FAQ.map(([q, a]) => `        <details class="faq"><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join("\n");

